// =========================================================================
// 15_MYTHIC_PAWMI_ELECTRIC_BEAR - Modern HTML5 Canvas 2D Implementation
// 100% Anatomical Likeness & High-End 3D Pop Mart Vinyl Aesthetic
// Organic Micro-Physics: 5% Squash & Stretch, Ears Jiggle Lag 0.45 rad, Twitching Sparks
// =========================================================================

function drawPawmiElectricBear(ctx, cx, cy, scale, t, manualBlink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  // 1. Organic Micro-Physics Kinematics
  const breathFreq  = 2.2; // Tần số nhịp thở êm ái
  const breathPhase = t * breathFreq;
  const breathSin   = Math.sin(breathPhase);

  // Squash & Stretch 5% bảo toàn thể tích (sY * sX ≈ 1.0)
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const bounceY = -Math.abs(breathSin) * 3.5;
  const by = bounceY; // Tọa độ Y động

  // Hai tai gấu rung rinh trễ pha Delta Phi = 0.45 rad
  const earLag   = breathPhase - 0.45;
  const earRotL  = Math.sin(earLag) * 0.055;
  const earRotR  = -Math.sin(earLag) * 0.045;

  // Chỏm bờm lông trán uốn lượn trễ pha Delta Phi = 0.30 rad
  const tuftLag  = breathPhase - 0.30;
  const tuftSwayX = Math.sin(tuftLag) * 2.8;

  // Xung điện lách tách tần số cao
  const sparkF1 = Math.sin(t * 16.0) * 3.5;
  const sparkF2 = Math.cos(t * 14.0) * 3.5;
  const sparkF3 = Math.sin(t * 20.0) * 3.0;

  // Nhịp chớp mắt 3.5s (interval 3500ms, duration 140ms)
  const blinkCycle = (t * 1000) % 3500;
  const blink = manualBlink || (blinkCycle < 140);

  // 2. LAYER 0: BÓNG TIẾP XÚC MẶT SÀN CO GIÃN ÊM ÁI (Ground Contact Shadow)
  ctx.save();
  const shadowScale = (1.0 - bounceY * 0.04);
  const shadowW = 92 * sX * shadowScale;
  const shadowH = 16 * sX * shadowScale;
  const shadowGrad = ctx.createRadialGradient(-2, 86, 4, -2, 86, shadowW);
  shadowGrad.addColorStop(0, "rgba(40, 20, 10, 0.75)");
  shadowGrad.addColorStop(0.5, "rgba(45, 24, 12, 0.35)");
  shadowGrad.addColorStop(1, "rgba(45, 24, 12, 0.0)");
  ctx.fillStyle = shadowGrad;
  ctx.beginPath();
  ctx.ellipse(-2, 86, shadowW, shadowH, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // 3. LAYER 1: ĐUÔI KEM & BÀN CHÂN SAU (Tail & Hind Foot)
  ctx.save();
  ctx.translate(0, by);

  // Đuôi kem phúng phính vểnh sau lưng bên phải
  const tailGrad = ctx.createRadialGradient(74 + tuftSwayX, -50, 4, 74 + tuftSwayX, -50, 24);
  tailGrad.addColorStop(0, "#FFF5E4");
  tailGrad.addColorStop(0.7, "#F6DEC0");
  tailGrad.addColorStop(1, "#D4AC82");
  ctx.fillStyle = tailGrad;
  ctx.beginPath();
  ctx.ellipse(74 + tuftSwayX, -48, 16, 26, 0.3, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(78 + tuftSwayX, -62, 12, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = "#4A2810";
  ctx.lineWidth = 1.4;
  ctx.stroke();

  // Bàn chân sau phải peeking out dưới sườn
  ctx.fillStyle = "#BD5213";
  ctx.beginPath();
  ctx.roundRect(80, 64, 20, 13, 5);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(97, 71, 4.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = "#381808";
  ctx.lineWidth = 1.4;
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(86, 77); ctx.lineTo(86, 70);
  ctx.moveTo(92, 77); ctx.lineTo(92, 70);
  ctx.stroke();

  ctx.restore();

  // 4. LAYER 2: THÂN HÌNH QUẢ CẦU BÉO MẬP CHIBI POP MART (Rotund Torso Sphere)
  ctx.save();
  ctx.translate(0, by);

  const bodyGrad = ctx.createRadialGradient(44, 4, 12, 34, 22, 75);
  bodyGrad.addColorStop(0, "#FFA947");
