function drawPawmiEye(ctx, ex, ey, rx, ry, rot, blink) {
  ctx.save();
  ctx.translate(ex, ey);
  ctx.rotate(rot);

  if (blink) {
    // Mí mắt nhắm cong hình lưỡi liềm ngọt ngào
    ctx.strokeStyle = "#1A1115";
    ctx.lineWidth = 3.2;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.arc(0, 3, rx * 0.85, Math.PI * 0.12, Math.PI * 0.88);
    ctx.stroke();
    // Khóe vểnh nhẹ
    ctx.beginPath();
    ctx.moveTo(rx * 0.7, 4); ctx.lineTo(rx * 1.1, 1);
    ctx.moveTo(-rx * 0.7, 4); ctx.lineTo(-rx * 1.1, 1);
    ctx.stroke();
  } else {
    // 1. Viền mí & hốc mắt đen tuyền
    ctx.beginPath();
    ctx.ellipse(0, 0, rx, ry, 0, 0, Math.PI * 2);
    ctx.fillStyle = "#1A1115";
    ctx.fill();
    ctx.strokeStyle = "#381808";
    ctx.lineWidth = 1.6;
    ctx.stroke();

    // 2. Tròng mắt đen nhánh hạt pha lê
    const eyeGrad = ctx.createLinearGradient(0, -ry, 0, ry);
    eyeGrad.addColorStop(0, "#1A1115");
    eyeGrad.addColorStop(0.5, "#25181E");
    eyeGrad.addColorStop(0.78, "#3D252E");
    eyeGrad.addColorStop(1, "#D97736");
    ctx.beginPath();
    ctx.ellipse(0, 0, rx - 1.2, ry - 1.2, 0, 0, Math.PI * 2);
    ctx.fillStyle = eyeGrad;
    ctx.fill();

    // Vòm sáng caustic đáy mắt hổ phách
    ctx.beginPath();
    ctx.ellipse(0, ry * 0.38, rx * 0.68, ry * 0.44, 0, 0, Math.PI);
    ctx.fillStyle = "rgba(245, 155, 66, 0.65)";
    ctx.fill();

    // 3. 3 ĐIỂM BẮT SÁNG PHA LÊ (3-Point Specular Highlights)
    // Điểm 1: Primary Keylight Specular (Bầu dục lớn góc 11h)
    ctx.fillStyle = "#FFFFFF";
    ctx.beginPath();
    ctx.ellipse(-rx * 0.22, -ry * 0.35, rx * 0.38, ry * 0.28, -0.25, 0, Math.PI * 2);
    ctx.fill();

    // Điểm 2: Secondary Caustic Specular (Tròn vừa góc 5h)
    ctx.fillStyle = "rgba(255, 245, 230, 0.95)";
    ctx.beginPath();
    ctx.arc(rx * 0.26, ry * 0.32, rx * 0.20, 0, Math.PI * 2);
    ctx.fill();

    // Điểm 3: Tertiary Micro Glint (Tia sáng vi điểm mép ngoài)
    ctx.fillStyle = "#FFFFFF";
    ctx.beginPath();
    ctx.arc(rx * 0.40, -ry * 0.05, rx * 0.12, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

function drawElectricSpark(ctx, x, y, scale, color) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(scale, scale);
  ctx.shadowColor = color;
  ctx.shadowBlur = 10;
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(0, -7);
  ctx.quadraticCurveTo(0, 0, 7, 0);
  ctx.quadraticCurveTo(0, 0, 0, 7);
  ctx.quadraticCurveTo(0, 0, -7, 0);
  ctx.quadraticCurveTo(0, 0, 0, -7);
  ctx.fill();
  ctx.fillStyle = "#FFFFFF";
  ctx.beginPath();
  ctx.arc(0, 0, 2.0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}
